package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;
public class WimTreeTest {
 static int checks;static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;}
 public static void main(String[] args)throws Exception{Path temp=Files.createTempDirectory("usbwb-wimtree-");File libs=new File("app/src/main/jniLibs/arm64-v8a");try{
 Path in=Files.createDirectories(temp.resolve("in/folder"));byte[] hello="Owned WIM folder test".getBytes("UTF-8"),arabic="اختبار عربي".getBytes("UTF-8");Files.write(in.resolve("hello.txt"),hello);Files.write(in.resolve("ورشة.txt"),arabic);Files.createFile(in.resolve("empty"));Files.createDirectory(in.resolve("subdir"));Files.write(temp.resolve("in/outside.txt"),new byte[]{1,2});Files.createSymbolicLink(in.resolve("link"),Paths.get("hello.txt"));File wim=temp.resolve("owned.wim").toFile();WimTest.command(libs,"capture",temp.resolve("in").toString(),wim.toString(),"--compress=LZX","--threads=1","--check","--quiet");byte[] original=Files.readAllBytes(wim.toPath());
 try(OpticalImage.Source source=WimTest.source(wim)){
 ArchiveTools.Manifest whole=ArchiveTools.scanWim(libs,source,1,"/",1048576,(a,b)->{},()->false);check(whole.entries.stream().anyMatch(e->e.path.equals("outside.txt")),"root listing includes outside file without empty-root failure");
 ArchiveTools.Manifest m=ArchiveTools.scanWim(libs,source,1,"/folder",1048576,(a,b)->{},()->false);check(m.total==hello.length+arabic.length,"bounded folder total");check(m.entries.size()==6,"folder subtree including directory/empty/link");check(m.entries.stream().noneMatch(e->e.path.equals("outside.txt")),"subtree isolation");check(m.entries.stream().anyMatch(e->e.special&&e.path.endsWith("link")),"link omitted");Map<String,ArchiveTools.MemoryFile> output=new HashMap<>();Map<String,String> hashes=ArchiveTools.extract(libs,source,m,new WimFiles.Store(){public void capacity(long n){}public WimFiles.RandomFile create(String n){ArchiveTools.MemoryFile f=new ArchiveTools.MemoryFile();output.put(n,f);return f;}},(a,b)->{},()->false);
 check(hashes.size()==3,"all regular/empty exports");for(ArchiveTools.Entry e:m.entries)if(!e.directory&&!e.special){byte[] expected=Files.readAllBytes(temp.resolve("in").resolve(e.path));check(Arrays.equals(output.get(e.output()).data(),expected),"independent byte comparison "+e.path);}
 for(String root:new String[]{"/../escape","/missing"})try{ArchiveTools.scanWim(libs,source,1,root,1048576,(a,b)->{},()->false);throw new AssertionError("root accepted");}catch(IOException expected){checks++;}
 try{ArchiveTools.scanWim(libs,source,1,"/",1,(a,b)->{},()->false);throw new AssertionError("size limit accepted");}catch(IOException expected){checks++;}
 try{ArchiveTools.scanWim(libs,source,2,"/",1048576,(a,b)->{},()->false);throw new AssertionError("index accepted");}catch(IOException expected){checks++;}
 try{ArchiveTools.scanWim(libs,source,1,"/",1048576,(a,b)->{},()->true);throw new AssertionError("cancel accepted");}catch(IOException expected){check(expected.getMessage().equals("CANCELLED"),"cancel");}
 try{ArchiveTools.extract(libs,source,m,new WimFiles.Store(){public void capacity(long n){}public WimFiles.RandomFile create(String n){return new WimFiles.RandomFile(){public long size(){return 0;}public int read(long at,byte[] b){return 0;}public void write(long at,byte[] b){}public void truncate(long n){}public void sync(){}public void close(){}};}},(a,b)->{},()->false);throw new AssertionError("ignored output write");}catch(IOException expected){checks++;}
 check(ArchiveTools.listing(m).startsWith("WIMTREE_LIST\n"),"WIM listing marker");}
 check(Arrays.equals(original,Files.readAllBytes(wim.toPath())),"source completely unchanged");Path many=Files.createDirectory(temp.resolve("many"));for(int i=0;i<1001;i++)Files.createFile(many.resolve("file"+i));File over=temp.resolve("over.wim").toFile();WimTest.command(libs,"capture",many.toString(),over.toString(),"--compress=LZX","--threads=1","--quiet");try(OpticalImage.Source input=WimTest.source(over)){try{ArchiveTools.scanWim(libs,input,1,"/",1048576,(a,b)->{},()->false);throw new AssertionError("1000-file limit");}catch(IOException expected){checks++;}}
 System.out.println("PASS: "+checks+" actual WIM subtree/Arabic/empty/link/CRC RPC/readback/limit/source assertions");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(temp)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(Exception ignored){}});}}}
}
